const body = $json.body || $json;

let raw_log;
let source_id;

// Si body est une string : Content-Type text/plain → le body EST le log
if (typeof body === "string") {
  raw_log   = body;
  source_id = "unknown";
} else {
  // Content-Type application/json → body a les champs raw_log et source_id
  raw_log   = body.raw_log   ?? null;
  source_id = body.source_id || "unknown";
}

function detectFormat(log) {
  if (!log || typeof log !== "string" || log.trim() === "") return "unknown";

  // JSON : commence par {
  if (log.trimStart().startsWith("{")) return "json";

  // Apache : commence par une IP suivie de "METHOD
  if (/^\d+\.\d+\.\d+\.\d+.*"(GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS)/.test(log)) return "apache";

  // Syslog : Mois JJ HH:MM:SS hostname process[pid]:
  if (/^[A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}\s+\S+\s+\S+\[/.test(log)) return "syslog";

  // Plaintext : commence par une date YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}/.test(log)) return "plaintext";

  return "unknown";
}

return {
  raw_log,
  source_id,
  format_type: detectFormat(raw_log)
};

const rawStr = $json.raw_log;
const bodySourceId = $json.source_id || "unknown";

let log = {};
try {
  log = typeof rawStr === "string" ? JSON.parse(rawStr) : {};
} catch(e) { log = {}; }

// Préfixer le message avec le level pour que les regex le capturent
const level   = log.level || "";
const message = log.message || JSON.stringify(log);
const fullMessage = level ? `${level}: ${message}` : message;

return {
  source_id:     log.service || log.source_id || bodySourceId,
  log_timestamp: log.timestamp || new Date().toISOString(),
  raw_log:       rawStr,
  message:       fullMessage,
  format_type:   "json"
};

const log = $json.raw_log;

const match = typeof log === "string"
  ? log.match(/^[A-Z][a-z]{2}\s+\d+\s+\d+:\d+:\d+\s+\S+\s+(\S+)\[\d+\]:\s+(.*)$/)
  : null;

return {
  source_id: match?.[1] || $json.source_id || "unknown",
  log_timestamp: new Date().toISOString(),
  raw_log: log,
  message: match?.[2] || log,
  format_type: "syslog"
};

const log = $json.raw_log;

const match = typeof log === "string"
  ? log.match(/(\d+\.\d+\.\d+\.\d+).*?\[(.*?)\]\s+"(.*?)"\s+\d+\s+\d+(.*)/)
  : null;

// match[3] = la requête HTTP  ("POST /api/checkout")
// match[4] = tout ce qui suit (CRITICAL: Database connection pool exhausted)
const requestPart  = match?.[3] || "";
const trailingPart = match?.[4]?.trim() || "";

return {
  source_id:     $json.source_id || "apache",
  log_timestamp: match?.[2] || new Date().toISOString(),
  raw_log:       log,
  message:       trailingPart
                   ? `${requestPart} ${trailingPart}`
                   : (requestPart || log),
  format_type:   "apache"
};

const log = $json.raw_log;

const parts = typeof log === "string" ? log.split(" ") : [];

return {
  source_id: $json.source_id || "unknown",
  log_timestamp: parts.slice(0, 2).join(" ") || new Date().toISOString(),
  raw_log: log,
  message: parts.slice(2).join(" ") || log,
  format_type: "text"
};

return {
  source_id: $json.source_id || "unknown",
  log_timestamp: new Date().toISOString(),
  raw_log: $json.raw_log,
  message: $json.raw_log,
  format_type: "unknown"
};

// 0. CONFIG
const TIMEOUT_WINDOW_SEC  = parseInt($env.TIMEOUT_WINDOW    ?? '300', 10);
const CASCADE_THRESHOLD   = parseInt($env.CASCADE_THRESHOLD ?? '3',   10);
const CASCADE_WINDOW_SEC  = parseInt($env.CASCADE_WINDOW    ?? '60',  10);

const EFFECTIVE_TIMEOUT   = Number.isFinite(TIMEOUT_WINDOW_SEC)  && TIMEOUT_WINDOW_SEC  > 0 ? TIMEOUT_WINDOW_SEC  : 300;
const EFFECTIVE_THRESHOLD = Number.isFinite(CASCADE_THRESHOLD)   && CASCADE_THRESHOLD   > 0 ? CASCADE_THRESHOLD   : 3;
const EFFECTIVE_CASCADE   = Number.isFinite(CASCADE_WINDOW_SEC)  && CASCADE_WINDOW_SEC  > 0 ? CASCADE_WINDOW_SEC  : 60;

// 1. TRANSITION TABLE 6×6
const TRANSITIONS = {
  INFO:          { sigma_info:'INFO',     sigma_warn:'WARNING',  sigma_error:'ERROR',    sigma_crit:'CRITICAL', sigma_ack:'INFO',     sigma_malformed:'INFO',          sigma_timeout:'INFO'  },
  WARNING:       { sigma_info:'INFO',     sigma_warn:'WARNING',  sigma_error:'ERROR',    sigma_crit:'CRITICAL', sigma_ack:'WARNING',  sigma_malformed:'WARNING',       sigma_timeout:'INFO'  },
  ERROR:         { sigma_info:'WARNING',  sigma_warn:'WARNING',  sigma_error:'ERROR',    sigma_crit:'CRITICAL', sigma_ack:'ERROR',    sigma_malformed:'ERROR',         sigma_timeout:'INFO'  },
  ERROR_CASCADE: { sigma_info:'WARNING',  sigma_warn:'ERROR',    sigma_error:'ERROR',    sigma_crit:'CRITICAL', sigma_ack:'ERROR',    sigma_malformed:'ERROR_CASCADE', sigma_timeout:'INFO'  },
  CRITICAL:      { sigma_info:'CRITICAL', sigma_warn:'CRITICAL', sigma_error:'CRITICAL', sigma_crit:'CRITICAL', sigma_ack:'RECOVERY', sigma_malformed:'CRITICAL',      sigma_timeout:'INFO'  },
  RECOVERY:      { sigma_info:'INFO',     sigma_warn:'WARNING',  sigma_error:'ERROR',    sigma_crit:'CRITICAL', sigma_ack:'RECOVERY', sigma_malformed:'RECOVERY',      sigma_timeout:'INFO'  },
};

// 2. REGEX PATTERNS
const REGEX_PATTERNS = [
  { symbol: 'sigma_crit',  pattern: /\b(CRITICAL|FATAL|EMERGENCY|PANIC|EMERG|KERN_CRIT|SEV1|P1)\b/i },
  { symbol: 'sigma_error', pattern: /\b(ERROR|Exception|Traceback|FAILED|FAILURE|5[0-9]{2}|NullPointer|OutOfMemory|Segfault|SIGSEGV|SIGABRT)\b/i },
  { symbol: 'sigma_warn',  pattern: /\b(WARN|WARNING|SLOW|RETRY|DEPRECATED|TIMEOUT(?!_WINDOW)|HIGH_LATENCY|BACKPRESSURE|THROTTL)\b/i },
  { symbol: 'sigma_info',  pattern: /\b(INFO|DEBUG|TRACE|OK|SUCCESS|STARTED|STOPPED|HEALTHY|2[0-9]{2}|CONNECTED|INITIALIZED)\b/i },
];
const ACK_PATTERN = /\b(__AFD_ACK__)\b/;

function evaluateSymbol(message) {
  if (message === null || message === undefined) return 'sigma_malformed';
  if (typeof message !== 'string' || message.trim() === '') return 'sigma_malformed';
  if (ACK_PATTERN.test(message)) return 'sigma_ack';
  for (const { symbol, pattern } of REGEX_PATTERNS) {
    if (pattern.test(message)) return symbol;
  }
  return 'sigma_malformed';
}

function applyTransition(state, symbol) {
  const row = TRANSITIONS[state];
  if (!row) return TRANSITIONS['INFO'][symbol] ?? 'INFO';
  return row[symbol] ?? state;
}

// 3. READ LOG
const logObject = $('Insert rows in a table').item.json;
const sourceId  = logObject.source_id ?? 'unknown';
const message   = logObject.message   ?? '';
const logId     = logObject.id        ?? null;
const now       = new Date();

// 4. READ AFD STATE
const stateRow = $json;

let rawState = stateRow?.current_state ?? 'INFO';
if (rawState === 'NOMINAL')  rawState = 'INFO';
if (rawState === 'DEGRADED') rawState = 'WARNING';
let currentState = TRANSITIONS[rawState] ? rawState : 'INFO';

const isNewService      = stateRow?.is_new_service !== false;
const cascadeCount      = parseInt(stateRow?.cascade_count ?? '0', 10) || 0;
const elapsedSec        = Number(stateRow?.elapsed_since_last_sec ?? 999999);
const cascadeElapsedSec = Number(stateRow?.cascade_elapsed_sec   ?? 999999);

// 5. TEMPORAL RESET
let stateAfterTimeout = currentState;
let timeoutApplied    = false;
let newCascadeCount   = cascadeCount;

if (!isNewService && elapsedSec > EFFECTIVE_TIMEOUT) {
  stateAfterTimeout = applyTransition(currentState, 'sigma_timeout');
  timeoutApplied    = true;
  newCascadeCount   = 0;
}

// 6. SYMBOL + TRANSITION + CASCADE WINDOW
const symbol      = evaluateSymbol(message);
const rawNewState = applyTransition(stateAfterTimeout, symbol);

let newState      = rawNewState;
let cascade_reset = 'keep';

if (rawNewState === 'ERROR') {
  if (cascadeElapsedSec > EFFECTIVE_CASCADE) {
    newCascadeCount = 1;
    cascade_reset   = 'reset_now';
    newState        = 'ERROR';
  } else {
    newCascadeCount = cascadeCount + 1;
    cascade_reset   = 'keep';
    if (newCascadeCount >= EFFECTIVE_THRESHOLD) {
      newState = 'ERROR_CASCADE';
    }
  }
} else if (rawNewState === 'ERROR_CASCADE') {
  newCascadeCount = cascadeCount + 1;
  cascade_reset   = 'keep';
} else {
  if (currentState === 'ERROR' || currentState === 'ERROR_CASCADE') {
    newCascadeCount = 0;
    cascade_reset   = 'reset_null';
  }
}

const previousState = currentState;

// 7. OUTPUT
return {
  ...logObject,
  afd_symbol:        symbol,
  afd_state:         newState,
  previous_state:    previousState,
  source_id:         sourceId,
  id:                logId,
  cascade_count:     newCascadeCount,
  cascade_reset:     cascade_reset,
  is_new_service:    isNewService,
  timeout_applied:   timeoutApplied,
  elapsed_sec:       Math.round(elapsedSec),
  cascade_elapsed:   Math.round(cascadeElapsedSec),
  cascade_threshold: EFFECTIVE_THRESHOLD,
  cascade_window:    EFFECTIVE_CASCADE,
  engine_ts:         now.toISOString(),
  engine_version:    'v2',
};

const originalLog = $('AFD Engine').first().json;
const rows = $input.all();
const recent_logs = rows.map(r => r.json.message);

return [{
  json: {
    ...originalLog,
    recent_logs
  }
}];

const log = $input.first().json;

const actions = Array.isArray(log.actions_immediates)
  ? log.actions_immediates
  : [];

const timestamp = new Date().toISOString();

/**
 * Format all actions
 */
const actionsText = actions.length
  ? actions.map((a, i) => `${i + 1}. ${a}`).join('\n')
  : "N/A";

/**
 * WhatsApp Message 
 */
const whatsappMessage = `
CRITICAL — ${log.source_id}

${log.message?.slice(0, 200)}

Cause probable:
${log.cause_probable}

Actions:
${actionsText}

${timestamp}

Reply:
ACK — Prise en charge
FALSE-POSITIVE — Faux positif
CORRIGER-WARNING — Reclassifier warning
CORRIGER-ERROR — Reclassifier error
RESOLVED — Incident résolu
STATUS — État du système
ESCALATE — Escalader
HELP — Aide
`;

/**
 * HTML Email (no emojis)
 */
const htmlMessage = `
<h2>CRITICAL Alert</h2>

<p><b>Service:</b> ${log.source_id}</p>

<p><b>Message:</b><br>${log.message}</p>

<p><b>Cause probable:</b><br>${log.cause_probable}</p>

<p><b>Actions:</b></p>
<ul>
${actions.map(a => `<li>${a}</li>`).join('')}
</ul>

<p><b>Timestamp:</b> ${timestamp}</p>
`;

return [
  {
    json: {
      ...log,
      whatsappMessage,
      htmlMessage,
      alert_timestamp: timestamp
    }
  }
];

