const services = $input.all().map(item => ({
  source_id: item.json.source_id,
  state: item.json.current_state,
  last_event_time: item.json.last_event_time
}));

const prompt = `
You are an expert SRE incident correlation engine.

Multiple services are simultaneously in CRITICAL state.

Analyze possible correlations and shared root causes.

Services:
${JSON.stringify(services, null, 2)}

Respond ONLY in JSON:
{
  "global_incident": true,
  "possible_root_cause": "...",
  "recommended_action": "...",
  "severity": "HIGH"
}
`;

return [{
  json: {
    services,
    llm_payload: {
      model: $env.GROQ_MODEL ?? 'llama-3.1-8b-instant',
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ],
      temperature: 0.2,
      max_tokens: 250,
      response_format: {
        type: "json_object"
      }
    }
  }
}];

const httpResult = $json;

if (httpResult.error || !httpResult.choices) {
  return [{
    json: {
      global_incident: true,
      possible_root_cause: 'Unable to determine root cause',
      recommended_action: 'Manual investigation required',
      severity: 'HIGH',
      llm_source: 'fallback'
    }
  }];
}

try {
  const rawText = httpResult.choices[0].message.content.trim();
  const parsed = JSON.parse(rawText);

  return [{
    json: {
      global_incident: parsed.global_incident ?? true,
      possible_root_cause: parsed.possible_root_cause,
      recommended_action: parsed.recommended_action,
      severity: parsed.severity ?? 'HIGH',
      llm_source: 'groq'
    }
  }];
} catch (e) {
  return [{
    json: {
      global_incident: true,
      possible_root_cause: 'Correlation parsing failed',
      recommended_action: 'Investigate all affected services',
      severity: 'HIGH',
      llm_source: 'fallback'
    }
  }];
}

